// Separate tracking namespace for Meta API to prevent collision with open-wa
const staticData = $getWorkflowStaticData('global');
if (!staticData.sentPhonesMeta) staticData.sentPhonesMeta = {};

const allRows = items.map(item => item.json);
const unsent = allRows.filter(row => {
  const phone = String(row.phone || '').replace(/\D/g, '');
  return !staticData.sentPhonesMeta[phone];
});

return unsent.map(row => ({ json: row }));

const row = $json;
const config = $('Meta Credentials & Config').item.json;

// Normalize phone to E.164 without '+' sign (e.g. 9665XXXXXXXX)
let phone = String(row.phone || '').replace(/\D/g, '');
if (phone.startsWith('05') && phone.length === 10) {
  phone = '966' + phone.substring(1);
} else if (phone.startsWith('5') && phone.length === 9) {
  phone = '966' + phone;
}

const adTitle = String(row.ad || 'الإعلان').trim();

// Meta WhatsApp Cloud API Template Payload format
const metaPayload = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: phone,
  type: 'template',
  template: {
    name: config.templateName || 'haraj_ad_inquiry',
    language: {
      code: config.languageCode || 'ar'
    },
    components: [
      {
        type: 'body',
        parameters: [
          {
            type: 'text',
            text: adTitle
          }
        ]
      }
    ]
  }
};

return [{
  json: {
    ...row,
    cleanPhone: phone,
    metaPayload,
    apiUrl: `https://graph.facebook.com/v20.0/${config.phoneNumberId}/messages`,
    authHeader: `Bearer ${config.accessToken}`
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.sentPhonesMeta) staticData.sentPhonesMeta = {};

const item = $('Prepare Meta Payload').item.json;
const phone = item.cleanPhone;
const msgId = $json.messages?.[0]?.id || 'unknown_id';

staticData.sentPhonesMeta[phone] = {
  sent_at: new Date().toISOString(),
  meta_msg_id: msgId
};

return [{ json: { ...item, meta_msg_id: msgId, success: true } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.sentPhonesMeta) staticData.sentPhonesMeta = {};
if (!staticData.failCountsMeta) staticData.failCountsMeta = {};

const item = $('Prepare Meta Payload').item.json;
const phone = item.cleanPhone;
const errorMessage = $json.error?.message || (typeof $json === 'string' ? $json : JSON.stringify($json));

staticData.failCountsMeta[phone] = (staticData.failCountsMeta[phone] || 0) + 1;

const MAX_RETRIES = 3;
let gaveUp = false;
if (staticData.failCountsMeta[phone] >= MAX_RETRIES) {
  staticData.sentPhonesMeta[phone] = {
    sent_at: new Date().toISOString(),
    gaveUpAfterError: errorMessage
  };
  gaveUp = true;
}

return [{ json: { ...item, error: errorMessage, attempt: staticData.failCountsMeta[phone], gaveUp, success: false } }];
